text:
/* Public-page tokens are isolated from the workspace palette. */
.landing {
  --separator: color-mix(in srgb, var(--landing-muted) 85%, transparent);
  --landing-bg: var(--color-landing-landing-bg-1);
  --landing-fg: var(--color-landing-landing-fg-2);
  --landing-muted: var(--color-landing-landing-muted-3);
  --landing-muted2: var(--color-landing-landing-muted2-4);
  --landing-faint: var(--color-landing-landing-faint-5);
  --landing-card: var(--color-landing-landing-card-6);
  --landing-line: var(--color-landing-landing-line-7);
  --landing-line2: var(--color-landing-landing-line2-8);
  --landing-line3: var(--color-landing-landing-line3-9);
  --landing-ok: var(--color-landing-landing-ok-10);
  --landing-accent: var(--color-landing-landing-accent-11);
  --landing-accent-text: var(--color-landing-landing-accent-11);
  --landing-on-accent: var(--color-landing-landing-bg-1);
  --landing-violet: var(--color-landing-landing-violet-12);
  --card-hover-accent: var(--landing-violet);
  --card-hover-secondary: var(--landing-pink);
  --landing-pink: var(--color-landing-landing-pink-13);
  --landing-amber: var(--color-landing-landing-amber-14);
  --landing-green: var(--color-landing-landing-green-15);
  --landing-red: var(--color-landing-landing-red-16);
  --landing-green-text: var(--landing-green);
  --landing-amber-text: var(--landing-amber);
  --landing-brand-gradient: linear-gradient(
    90deg,
    var(--color-landing-landing-violet-12),
    var(--color-landing-landing-pink-13)
  );
  --landing-complete-gradient: linear-gradient(
    135deg,
    var(--color-landing-landing-complete-gradient-17),
    var(--color-landing-landing-complete-gradient-18)
  );
}
[data-theme="light"] .landing {
  --landing-bg: var(--color-landing-landing-bg-19);
  --landing-fg: var(--color-landing-landing-fg-20);
  --landing-muted: var(--color-landing-landing-muted-21);
  --landing-muted2: var(--color-landing-landing-muted2-22);
  --landing-faint: var(--color-landing-landing-faint-23);
  --landing-card: var(--color-landing-landing-card-24);
  --landing-line: var(--color-landing-landing-line-25);
  --landing-line2: var(--color-landing-landing-line2-26);
  --landing-line3: var(--color-landing-landing-line3-27);
  --landing-ok: var(--color-landing-landing-ok-28);
  --landing-accent-text: var(--color-landing-landing-accent-text-29);
  --landing-amber: var(--color-landing-landing-amber-30);
  --landing-green: var(--color-landing-landing-green-31);
  --landing-red: var(--color-landing-landing-red-32);
  --landing-green-text: color-mix(
    in srgb,
    var(--landing-green) 75%,
    var(--landing-fg)
  );
  --landing-amber-text: var(--color-landing-landing-amber-text-33);
}
/* Also cover browser overscroll and the root skip-link focus color. */
html:has(.landing) {
  --landing-bg: var(--color-landing-landing-bg-1);
  --landing-violet: var(--color-landing-landing-violet-12);
  color-scheme: dark;
  background: var(--landing-bg);
  --ring: var(--color-landing-landing-accent-text-29);
}
html[data-theme="light"]:has(.landing) {
  --landing-bg: var(--color-landing-landing-bg-19);
  color-scheme: light;
  background: var(--landing-bg);
}
html[data-theme="dark"]:has(.landing) {
  --ring: var(--color-landing-landing-accent-11);
}
html:has(.landing),
.landing {
  --scrollbar-thumb: color-mix(
    in srgb,
    var(--landing-violet) 35%,
    var(--landing-bg)
  );
  --scrollbar-track: var(--landing-bg);
}
.landing h1,
.landing h2,
.landing h3,
.landing-logo {
  font-family: var(--font-sans);
}
.landing a:focus-visible,
.landing button:focus-visible {
  outline: 2px solid var(--landing-accent-text);
  outline-offset: 4px;
}
.landing-button {
  transition:
    translate 180ms ease,
    filter 180ms ease,
    transform 0.2s ease,
    box-shadow 0.2s ease;
}
.landing-button {
  --button-hover-filter: none;
}
.landing-button:hover {
  box-shadow: none;
}
.landing-gradient-text {
  -webkit-background-clip: text;
}
/* Darken the original gradient for accessible large text on a light surface. */
[data-theme="light"] .landing-gradient-text {
  filter: brightness(0.75);
}
.landing h2 {
  font-size: clamp(30px, 4vw, 44px);
  font-weight: 700;
  line-height: 1.1;
  letter-spacing: -0.02em;
  max-width: 640px;
}
@keyframes landing-card-enter {
  from {
    opacity: 0;
    transform: translateY(32px) scale(0.94);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

/* The hero palette stays local so the sections below retain their colors. */
.landing-navbar,
.landing-hero {
  --separator: color-mix(in srgb, var(--landing-muted) 85%, transparent);
  --landing-fg: var(--color-landing-landing-fg-34);
  --landing-muted: var(--color-landing-landing-muted-35);
  --landing-faint: var(--color-landing-landing-faint-36);
  --landing-accent: var(--color-landing-landing-accent-37);
  --landing-accent-text: var(--color-landing-landing-accent-text-38);
  --landing-on-accent: var(--color-landing-landing-on-accent-39);
  --landing-card: var(--color-landing-landing-card-40);
  --landing-line: var(--color-landing-landing-line-41);
  --landing-line2: var(--color-landing-landing-line2-42);
  --landing-line3: var(--color-landing-landing-line3-43);
  --landing-green: var(--color-landing-landing-green-44);
  --landing-green-text: var(--color-landing-landing-green-44);
  --landing-amber: var(--color-landing-landing-amber-45);
  --landing-amber-text: var(--color-landing-landing-amber-45);
  --landing-red: var(--color-landing-landing-red-46);
  color: var(--landing-fg);
}
.landing-hero {
  position: relative;
  isolation: isolate;
}
.landing-hero::before {
  content: "";
  position: absolute;
  z-index: -1;
  pointer-events: none;
}
.landing-hero h1 {
  max-width: none;
}
.landing-hero .landing-gradient-text {
  filter: none;
}
.landing-hero-cta {
  color: var(--color-landing-color-47);
  padding-inline: 20px;
  white-space: nowrap;
}
.landing-hero-legal a {
  text-decoration: underline;
  text-underline-offset: 3px;
}
.landing-hero-highlights {
  flex-wrap: wrap;
  list-style: none;
  padding: 0;
}
.landing-hero-highlights li {
  display: flex;
  align-items: center;
}
.landing-dashboard-perspective {
  min-width: 0;
}
.landing-batch {
  position: relative;
  animation: landing-dashboard-float 7s ease-in-out infinite;
  isolation: isolate;
  min-width: 0;
}
.landing-dashboard-perspective::before,
.landing-dashboard-perspective::after {
  content: "";
  position: absolute;
  z-index: -1;
  inset: 14px -9px -14px 12px;
  width: auto;
  height: auto;
  border: 1px solid var(--color-landing-border-48);
  border-radius: inherit;
  background: var(--color-landing-background-49);
  opacity: 1;
  pointer-events: none;
}
.landing-dashboard-perspective::after {
  z-index: -2;
}
.landing-status.is-complete {
  color: var(--landing-green-text);
}
.landing-batch-body {
  display: flex;
  align-items: center;
}
.landing-ring {
  position: relative;
  flex: 0 0 132px;
}
.landing-ring-svg {
  transform: rotate(-90deg);
}
.landing-progress-arc {
  transition: none;
}
.landing-countdown {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  font-family: var(--font-num);
}
.landing-countdown > span {
  line-height: 1.2;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}
.landing-countdown small {
  font-family: var(--font-mono);
  letter-spacing: 0.12em;
  color: var(--landing-faint);
}
.landing-segmented-bar span {
  height: 100%;
  transition: none;
}
.landing-batch[data-reset="true"] .landing-segmented-bar span,
.landing-batch[data-reset="true"] .landing-progress-arc {
  transition: none;
}
.landing-stat-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
}
.landing-stat {
  display: flex;
  flex-direction: column;
  min-width: 0;
  border: 1px solid var(--landing-line2);
}
.landing-stat-label {
  display: flex;
  align-items: center;
  color: var(--landing-muted);
}
.landing-stat-label i {
  border-radius: 50%;
  flex-shrink: 0;
}
.landing-stat-value {
  font-family: var(--font-num);
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}
.landing-stat-sub {
  color: var(--landing-faint);
}
.landing-batch-meta {
  display: flex;
  flex-wrap: wrap;
  color: var(--landing-muted);
  font-variant-numeric: tabular-nums;
}
.landing-batch-footnote {
  display: flex;
  align-items: center;
  gap: 8px;
  border: 1px solid var(--landing-line2);
  color: var(--landing-muted);
}
.landing-batch-footnote svg {
  flex-shrink: 0;
  color: var(--landing-accent);
}
.landing-activity-heading h2 {
  line-height: 1.5;
}
.landing-activity-heading > span {
  color: var(--landing-faint);
}
.landing-activity {
  list-style: none;
  padding: 0;
}
.landing-activity li {
  display: flex;
  align-items: center;
  border-bottom: 1px dotted var(--separator);
}
.landing-activity li:last-child {
  border: 0;
}
.landing-activity-icon {
  display: grid;
  place-items: center;
  flex-shrink: 0;
}
.landing-activity-person {
  display: flex;
  flex: 1;
  min-width: 0;
  flex-direction: column;
  gap: 2px;
}
.landing-activity-person strong {
  font-weight: 500;
}
.landing-activity-person > span,
.landing-activity-time {
  color: var(--landing-faint);
}
.landing-activity-status {
  color: var(--landing-accent-text);
}
[data-status="delivered"] .landing-activity-icon,
[data-status="delivered"] .landing-activity-status {
  color: var(--landing-green-text);
}
.landing-batch[data-paused="true"],
.landing-batch[data-visible="false"],
.landing-batch[data-suspended="true"] {
  animation-play-state: paused;
}
.landing-batch[data-paused="true"] *,
.landing-batch[data-suspended="true"] * {
  animation-play-state: paused;
}
[data-theme="light"] .landing-navbar,
[data-theme="light"] .landing-hero {
  --landing-fg: var(--color-landing-landing-fg-50);
  --landing-muted: var(--color-landing-landing-muted-51);
  --landing-faint: var(--color-landing-landing-faint-52);
  --landing-accent: var(--color-landing-landing-accent-53);
  --landing-accent-text: var(--color-landing-landing-accent-text-54);
  --landing-card: var(--color-landing-landing-card-55);
  --landing-line2: var(--color-landing-landing-line2-56);
  --landing-line3: var(--color-landing-landing-line3-57);
  --landing-green: var(--color-landing-landing-green-58);
  --landing-green-text: var(--color-landing-landing-green-text-59);
  --landing-amber: var(--color-landing-landing-amber-60);
  --landing-red: var(--color-landing-landing-red-61);
}
[data-theme="light"] .landing-hero::before {
  background:
    linear-gradient(to bottom, transparent 65%, var(--landing-bg)),
    radial-gradient(
      ellipse at 14% 42%,
      var(--landing-hero-left-glow),
      transparent 32%
    ),
    radial-gradient(
      ellipse at 85% 45%,
      var(--color-landing-background-63),
      transparent 55%
    ),
    var(--color-landing-background-62);
}
[data-theme="light"] .landing-hero .landing-gradient-text {
  background-image: linear-gradient(
    100deg,
    var(--color-landing-background-image-64),
    var(--color-landing-background-image-65)
  );
}
@media (max-width: 1199px) and (min-width: 1024px) {
  .landing-hero {
    grid-template-columns: minmax(0, 0.9fr) minmax(0, 1.1fr);
    gap: 24px;
  }
  .landing-batch {
    padding: 18px;
  }
  .landing-batch-body {
    gap: 12px;
  }
  .landing-ring {
    flex-basis: 100px;
    width: 100px;
    height: 100px;
  }
  .landing-countdown > span {
    font-size: 22px;
  }
}
@media (max-width: 1023px) {
  .landing-dashboard-perspective {
    width: 100%;
    margin-inline: auto;
  }
}
@media (min-width: 1024px) {
  .landing-hero {
    grid-template-columns: minmax(0, 0.95fr) minmax(0, 1.05fr);
    gap: 40px;
    padding-block: 44px 84px;
  }
}
/* Reference composition: broad typography, a luminous edge, and a larger live preview. */
.landing-hero {
  width: min(1440px, calc(100vw - 64px));
  left: 50%;
  transform: translateX(-50%);
  grid-template-columns: minmax(0, 0.91fr) minmax(0, 1.09fr);
  gap: 44px;
  padding-block: 160px 72px;
  min-height: 0;
}
.landing-hero::before {
  inset: 0 calc((100% - 100vw) / 2);
  background:
    linear-gradient(to bottom, transparent 65%, var(--landing-bg)),
    radial-gradient(
      ellipse at 14% 42%,
      var(--landing-hero-left-glow),
      transparent 32%
    ),
    radial-gradient(
      ellipse at 92% 28%,
      var(--color-landing-background-70),
      transparent 36%
    ),
    radial-gradient(
      ellipse at 47% 48%,
      var(--color-landing-background-71),
      transparent 35%
    ),
    radial-gradient(
      ellipse at 55% 100%,
      var(--color-landing-background-72),
      transparent 48%
    ),
    linear-gradient(
      160deg,
      var(--color-landing-background-73),
      var(--color-landing-background-74) 65%
    );
}
.landing-hero::after {
  content: "";
  position: absolute;
  z-index: -1;
  pointer-events: none;
  border-top: 2px solid var(--color-landing-border-top-75);
  filter: blur(2px);
}
.landing-hero h1 {
  font-size: clamp(56px, 5.4vw, 90px);
  line-height: 1.02;
  letter-spacing: -0.055em;
}
.landing-hero .landing-gradient-text {
  background-image: linear-gradient(
    120deg,
    var(--color-landing-background-image-76) 0%,
    var(--color-landing-background-image-77) 55%,
    var(--color-landing-background-image-78)
  );
}
.landing-hero .landing-eyebrow {
  font-size: 14px;
  letter-spacing: 0.1em;
  color: var(--color-landing-color-79);
  margin-bottom: 28px;
}
.landing-hero-copy {
  max-width: 590px;
  font-size: 20px;
  line-height: 1.6;
  color: var(--color-landing-color-80);
  margin-top: 28px;
}
.landing-hero-actions {
  margin-top: 36px;
  gap: 22px;
  flex-wrap: nowrap;
}
.landing-hero-cta {
  gap: 16px;
  min-height: 70px;
  padding: 14px 24px;
  border-radius: 999px;
  border: 1px solid var(--color-landing-border-81);
  font-size: 18px;
  font-weight: 500;
  background: linear-gradient(
    115deg,
    var(--color-landing-background-82),
    var(--color-landing-background-83) 60%,
    var(--color-landing-background-84)
  );
  box-shadow:
    inset 0 2px 9px var(--color-landing-box-shadow-85),
    0 0 35px var(--color-landing-box-shadow-86);
}
.landing-hero-cta > svg {
  width: 22px;
  height: 22px;
}
.landing-hero-actions > p {
  font-size: 13px;
  min-width: 114px;
  color: var(--color-landing-color-87);
}
.landing-hero-highlights {
  margin-top: 26px;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 16px;
}
.landing-hero-highlights li {
  gap: 12px;
  font-size: 13px;
  line-height: 1.55;
  color: var(--color-landing-color-88);
}
.landing-highlight-icon {
  display: grid;
  place-items: center;
  width: 48px;
  height: 48px;
  flex-shrink: 0;
  border: 1px solid var(--color-landing-border-89);
  border-radius: 13px;
  background: linear-gradient(
    135deg,
    var(--color-landing-background-90),
    var(--color-landing-background-91)
  );
  box-shadow: inset 0 1px 1px var(--color-landing-box-shadow-92);
}
.landing-hero-highlights svg {
  color: var(--color-landing-color-93);
}
.landing-dashboard-perspective {
  perspective: 1600px;
  padding: 0 8px 0 0;
}
.landing-batch {
  --landing-accent: var(--color-landing-landing-accent-94);
  --landing-green: var(--color-landing-landing-green-95);
  --landing-red: var(--color-landing-landing-red-96);
  --landing-green-text: var(--color-landing-landing-green-text-97);
  --landing-line2: var(--color-landing-landing-line2-98);
  --landing-line3: var(--color-landing-landing-line3-99);
  transform: rotateY(-10deg) rotateX(3deg) rotateZ(-1.5deg);
  border: 2px solid var(--color-landing-border-100);
  border-radius: 30px;
  background:
    linear-gradient(
      140deg,
      var(--color-landing-background-101),
      transparent 35%
    ),
    var(--color-landing-background-102);
  box-shadow:
    inset 0 0 0 6px var(--color-landing-box-shadow-103),
    inset 0 1px 20px var(--color-landing-box-shadow-104),
    0 0 8px var(--color-landing-box-shadow-105),
    0 0 28px var(--color-landing-box-shadow-106),
    0 15px 70px var(--color-landing-box-shadow-107);
}
.landing-dashboard-perspective::before {
  inset: 28px -20px -20px 24px;
  border: 1px solid var(--color-landing-border-108);
  background: linear-gradient(
    100deg,
    var(--color-landing-background-109),
    var(--color-landing-background-110)
  );
  box-shadow: 8px 0 18px var(--color-landing-box-shadow-111);
  border-radius: 28px;
}
.landing-dashboard-perspective::after {
  inset: 96px -38px -38px 40px;
  border-color: var(--color-landing-border-color-112);
  background: var(--color-landing-background-113);
  border-radius: 26px;
  opacity: 0.7;
}
@keyframes landing-dashboard-float {
  50% {
    transform: translateY(-9px) rotateY(-10deg) rotateX(3deg) rotateZ(-1.5deg);
  }
}
.landing-batch-label {
  font-family: var(--font-mono);
  font-weight: 400;
  text-transform: uppercase;
  letter-spacing: 0.14em;
  font-size: 16px;
}
.landing-status.is-sending {
  color: var(--color-landing-color-115);
}
.landing-status.is-complete {
  background: var(--color-landing-background-116);
}
.landing-batch-body {
  gap: 24px;
  margin-top: 24px;
}
.landing-ring {
  width: 166px;
  height: 166px;
  flex-basis: 166px;
}
.landing-ring-shadow {
  filter: drop-shadow(0 0 12px var(--color-landing-filter-117));
}
.landing-countdown > span {
  font-size: 31px;
  font-family: var(--font-mono);
}
.landing-countdown small {
  font-size: 10px;
}
.landing-stat-grid {
  gap: 12px;
  margin-top: 24px;
}
.landing-stat {
  padding: 14px 12px;
  min-height: 130px;
  border-radius: 13px;
  background: linear-gradient(
    135deg,
    var(--color-landing-background-118),
    var(--color-landing-background-119)
  );
}
.landing-stat-label {
  font-size: 13px;
  gap: 8px;
}
.landing-stat-label i {
  width: 9px;
  height: 9px;
  box-shadow: 0 0 10px var(--color-landing-box-shadow-120);
}
.landing-stat-value {
  font-size: 36px;
  line-height: 1.25;
  margin-block: 10px;
}
.landing-stat-sub {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  line-height: 1.5;
  margin-top: auto;
}
.landing-stat-sub svg {
  flex-shrink: 0;
}
.landing-batch-meta {
  justify-content: flex-start;
  gap: 16px;
  font-size: 12px;
  margin-top: 20px;
}
.landing-batch-footnote {
  font-size: 12px;
  padding: 13px 12px;
  margin-top: 18px;
  border-radius: 10px;
  background: var(--color-landing-background-121);
}
.landing-activity-heading h2 {
  font-family: var(--font-mono);
  text-transform: uppercase;
  letter-spacing: 0.12em;
  font-size: 12px;
  font-weight: 400;
}
.landing-activity-heading > span {
  font-size: 11px;
}
.landing-activity li {
  gap: 12px;
  font-size: 12px;
}
.landing-activity-icon {
  width: 34px;
  height: 34px;
  border-radius: 50%;
  font-size: 14px;
  color: var(--color-landing-color-122) !important;
  background: linear-gradient(
    145deg,
