/* Floating uses transform; hover uses translate so the motions never compete. */
.landing-batch {
  translate: 0 0;
  will-change: transform, translate;
  transition:
    translate 280ms cubic-bezier(0.2, 0.8, 0.2, 1),
    border-color 280ms ease;
}
.landing-batch .landing-stat {
  --stat-accent: var(--landing-green);
  transition:
    border-color 220ms ease,
    box-shadow 220ms ease,
    translate 220ms ease;
}
.landing-batch .landing-stat:nth-child(2) {
  --stat-accent: var(--landing-amber);
}
.landing-batch .landing-stat:nth-child(3) {
  --stat-accent: var(--landing-red);
}
@media (hover: hover) and (pointer: fine) {
  .landing-batch:hover {
    translate: 0 -4px;
  }
  .landing-batch .landing-stat:hover {
    border-color: var(--stat-accent);
    box-shadow:
      inset 0 0 0 1px color-mix(in srgb, var(--stat-accent) 45%, transparent),
      0 0 24px color-mix(in srgb, var(--stat-accent) 35%, transparent);
  }
}
.landing-countdown.is-complete {
