  display: grid;
  place-items: center;
  position: relative;
  width: 44px;
  height: 44px;
  min-width: 0;
  border-radius: 50%;
  background: linear-gradient(
    135deg,
    var(--color-landing-landing-complete-gradient-17),
    var(--color-landing-landing-complete-gradient-18)
  );
  box-shadow: 0 6px 20px var(--color-landing-box-shadow-150);
  color: var(--color-landing-white);
  animation: completion-badge-pop 600ms cubic-bezier(0.34, 1.56, 0.64, 1) both;
}
.landing-completion-check path {
  stroke-dasharray: 24;
  stroke-dashoffset: 0;
  animation: landing-completion-draw 400ms ease-out 200ms both;
}
.landing-countdown.is-complete small {
  color: var(--landing-green-text);
  font-weight: 600;
  font-size: 11px;
  letter-spacing: 0.04em;
}
.landing-completion-ripple {
  animation: landing-completion-ripple 800ms ease-out 100ms both;
}
.landing-countdown.is-complete small {
  animation: completion-label-enter 400ms ease-out 350ms both;
}
@keyframes landing-completion-ripple {
  from {
    opacity: 0.5;
    transform: scale(0.8);
  }
  to {
    opacity: 0;
    transform: scale(2.2);
  }
}
@keyframes landing-completion-draw {
  from {
    stroke-dashoffset: 24;
  }
  to {
    stroke-dashoffset: 0;
  }
}
